WITH filtered AS (SELECT *, FLOOR(duration_sec) AS duration_sec_whole, COALESCE(page, 'OTHER') AS resolved_page FROM web_events WHERE event_time > DATE '2023-03-30'), gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) + INTERVAL '7' DAY THEN 1 ELSE 0 END AS session_start_flag FROM filtered), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps) SELECT burst_id, COUNT(CASE WHEN event_type = 'click' THEN 1 END) AS click_count, COUNT(*) AS row_count FROM sessionized GROUP BY burst_id HAVING COUNT(CASE WHEN event_type = 'click' THEN 1 END) > 1;
